:root {
  --bg: #2b1e0f;
  --gold: #c9933a;
  --gold-light: #e8c97a;
  --cream: #f5ecd6;
  --rust: #8b3a1c;
  --border: #c9933a;
}

.badge {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  background-color: var(--bg);
  border: 3px solid var(--border);
  border-radius: 12px;
  padding: 20px 32px;
  width: 260px;
  outline: 2px solid var(--gold-light);
  outline-offset: -8px;
}

.badge-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.badge-series {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.2em;
  color: var(--gold);
  text-transform: uppercase;
}

.badge-title {
  font-size: 26px;
  font-weight: 800;
  color: var(--gold-light);
  margin: 0;
  letter-spacing: 0.05em;
}

.badge-subtitle {
  font-size: 11px;
  font-weight: 500;
  color: var(--cream);
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.compass-rose {
  position: relative;
  width: 90px;
  height: 90px;
  border: 2px solid var(--gold);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 4px 0;
}

.dir {
  position: absolute;
  font-size: 13px;
  font-weight: 800;
  color: var(--gold-light);
}

.north { top: 6px; left: 50%; transform: translateX(-50%); color: var(--rust); }
.south { bottom: 6px; left: 50%; transform: translateX(-50%); }
.east  { right: 8px; top: 50%; transform: translateY(-50%); }
.west  { left: 8px; top: 50%; transform: translateY(-50%); }

.center-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--gold);
  border: 2px solid var(--gold-light);
}

.badge-footer {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  border-top: 1px solid var(--gold);
  padding-top: 10px;
  width: 100%;
}

.badge-org {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
  color: var(--gold);
  text-transform: uppercase;
}

.badge-date {
  font-size: 11px;
  font-weight: 500;
  color: var(--cream);
}
